"""Build an evidence-led HyperFrames edition; no product UI is fabricated."""
from pathlib import Path
import json,shutil,html,re,textwrap
ROOT=Path(__file__).resolve().parent.parent
OLD=ROOT/'demo-video/quorum-hackathon'
P=ROOT/'demo-video/quorum-rubric'
for d in ['assets','compositions','docs','review']:(P/d).mkdir(parents=True,exist_ok=True)
for name in ['gsap.min.js','fonts/Montserrat.ttf','signal-to-noise.mp3','logo.svg']:
 dst=P/'assets'/Path(name).name;shutil.copy2(OLD/'assets'/name,dst)
for f in (OLD/'assets/rubric').glob('*.png'):shutil.copy2(f,P/'assets'/f.name)
for name in ['master.wav','voice-master.wav']:
 if (OLD/'assets/rubric'/name).exists():shutil.copy2(OLD/'assets/rubric'/name,P/'assets'/name)
proof=json.loads((ROOT/'SUBMISSION/evidence/current-run/proof.json').read_text())
advisory=json.loads((ROOT/'SUBMISSION/evidence/current-run/browser-advisory.json').read_text())
shutil.copy2(ROOT/'SUBMISSION/evidence/current-run/proof.json',P/'assets/proof.json')
shutil.copy2(ROOT/'SUBMISSION/evidence/current-run/browser-advisory.json',P/'assets/browser-advisory.json')
script=json.loads((OLD/'narration-rubric.json').read_text())
esc=lambda s:html.escape(str(s))
STYLE='''@font-face{font-family:Montserrat;src:url('assets/Montserrat.ttf')}*{box-sizing:border-box}html,body{margin:0;background:#101217;color:#f5f2ed;font-family:Montserrat,sans-serif}h1,h2,p{margin:0}h1{font-size:82px;line-height:1.1;letter-spacing:-.045em;font-weight:720}h2{font-size:53px;line-height:1.15;letter-spacing:-.03em}.eyebrow{font-size:28px;letter-spacing:.1em;font-weight:600;color:#ff9e92}.body{font-size:35px;line-height:1.42;color:#d5d8df}.small{font-size:28px;line-height:1.4;color:#c2c7d0}.accent{color:#ff9e92}.green{color:#82e9bf}.content{position:absolute;left:96px;right:96px;top:190px;bottom:178px}.header{position:absolute;left:96px;right:96px;top:62px;display:flex;justify-content:space-between;align-items:center;font-size:28px;letter-spacing:.08em;color:#c7cbd3}.header strong{font-size:34px;letter-spacing:.04em;color:#fff}.foot{position:absolute;left:96px;right:96px;bottom:142px;font-size:28px;color:#b1b8c5}.panel{padding:34px;border:1px solid #47505e;background:#1c2028;border-radius:14px}.row{display:flex;gap:32px}.rule{height:3px;background:#f06b5c;transform-origin:left}.imagebox{position:absolute;overflow:hidden;background:#14161b;border:1px solid #535c6a;border-radius:12px}.imagebox img{position:absolute;max-width:none}.toplabel{position:absolute;left:0;right:0;top:0;z-index:5;font-size:28px;background:#101217;padding:18px 24px;border-bottom:1px solid #535c6a;color:#fff}.code{font-family:monospace;white-space:pre-wrap;overflow-wrap:anywhere;font-size:32px;line-height:1.5;color:#dbe5ef}.value{font-size:140px;font-weight:650;letter-spacing:-.04em}.stack{display:grid;gap:22px}.pill{display:inline-block;border:1px solid #677284;padding:12px 19px;font-size:28px;border-radius:6px;color:#dce2ec}.stat{font-size:238px;line-height:1;letter-spacing:-.07em;font-weight:700}.shot{position:absolute;inset:0}.caption{position:absolute;left:140px;right:140px;bottom:38px;text-align:center;color:#fff;font-size:37px;line-height:1.3;font-weight:500}.caption span{display:inline-block;padding:12px 22px;background:#0a0c10;border:1px solid #3b424e;border-radius:7px}.native-source{font-size:28px;color:#b1b8c5;line-height:1.5}'''
scenes=script['scenes']
contents={
 'stakes':'''<div data-hold="Narrated evidence inspection" class="content"><div style="width:1080px"><p class="eyebrow">THE PUBLIC CONSEQUENCE</p><h1 style="margin-top:28px">A hospital cannot use a waiting tender.</h1><p class="body" style="margin-top:35px;width:980px">Procurement review connects public money to essential services.</p></div><div style="position:absolute;right:20px;top:62px;width:500px"><p class="stat accent">17%</p><p class="body" style="margin-top:20px">of GDP on average</p><p class="small">Public procurement across Africa</p></div><div class="panel" style="margin-top:58px;width:1728px"><p class="eyebrow">STARTING IN ZAMBIA</p><p class="body" style="margin-top:12px">One procurement officer. A complete file. A committee that can inspect the evidence.</p></div></div>''',
 'record':'''<div data-hold="Narrated evidence inspection" class="content"><div style="width:660px"><p class="eyebrow">ONE FICTIONAL ZAMBIA TENDER</p><h1 style="margin-top:24px;font-size:72px">Ten vaccine refrigerators.</h1><p class="body" style="margin-top:26px">ZMW 480,000 ceiling</p><p class="body">Two timely bids</p><div class="rule" style="margin:30px 0"></div><p class="body">60% technical capability</p><p class="body">40% delivery plan</p><p class="small" style="margin-top:25px">Issued 1 Oct · Closed 29 Oct</p><p class="small">Review 4 Nov 2026</p></div><div class="imagebox" style="left:730px;top:0;width:998px;height:650px"><img id="record-technical" class="clip" src="assets/criterion-technical.png" data-start="0" data-duration="11" data-track-index="0" style="width:998px;left:0;top:140px"><img id="record-delivery" class="clip" src="assets/criterion-delivery.png" data-start="11" data-duration="12" data-track-index="0" style="width:998px;left:0;top:140px"><span class="toplabel">ACTUAL PRODUCT CAPTURE</span></div></div>''',
 'model':f'''<div data-hold="Narrated evidence inspection" class="content"><div style="width:590px"><p class="eyebrow">META MODEL API</p><h1 style="font-size:66px;margin-top:24px">{esc(advisory['model'])}</h1><p class="body" style="margin-top:30px">{advisory['evidenceVerification']['verifiedQuotes']} exact source quotes verified</p><p class="small" style="margin-top:10px">{advisory['documentCount']} documents · {advisory['durationMs']/1000:.1f} seconds</p><div class="rule" style="margin:30px 0"></div><p class="body">“Delivery timing will be agreed after the award.”</p><p class="native-source" style="margin-top:16px">03-bid-demo-medical.md</p><p class="small accent" style="margin-top:26px">No signed delivery commitment evidenced.</p></div><div class="imagebox" style="left:650px;top:0;width:1078px;height:668px"><img id="model-provenance" class="clip" src="assets/provenance.png" data-start="0" data-duration="8" data-track-index="0" style="width:1078px;left:0;top:120px"><img data-layout-allow-overflow id="model-supported" class="clip" src="assets/supported-card.png" data-start="8" data-duration="12" data-track-index="0" style="width:1078px;left:0;top:-460px"><img id="model-gap" class="clip" src="assets/gap-card.png" data-start="20" data-duration="16" data-track-index="0" style="width:1040px;left:19px;top:90px"><span class="toplabel">LIVE RESPONSE · CAPTURED 4 NOV</span></div></div>''',
 'refusal':'''<div data-hold="Narrated evidence inspection" class="content"><p class="eyebrow">CAPTURED HTTP INTEGRATION TEST · FICTIONAL ACCOUNTS</p><h1 style="margin-top:24px">The gate holds.</h1><div class="row" style="margin-top:42px"><div id="refusal-unsigned" class="panel" style="width:545px"><p class="eyebrow">UNSIGNED REQUEST</p><p class="value accent">401</p><p class="body">Unattested mutation</p><p class="small" style="margin-top:22px">Direct service request refused.</p></div><div id="refusal-stepup" class="panel" style="width:545px"><p class="eyebrow">NO STEP-UP</p><p class="value accent">403</p><p class="body">Fresh signature required</p><p class="small" style="margin-top:22px">Signed-in account also refused.</p></div><div id="refusal-pending" class="panel" style="width:574px"><p class="eyebrow">AFTER BOTH ATTEMPTS</p><p class="green" style="font-size:65px;font-weight:650;margin:25px 0">PENDING</p><pre class="code">"receipt": null\n"stepUp": null\n"signature": null</pre></div></div><p class="body" style="margin-top:28px">Review graph → pending gate → END</p></div>''',
 'signature':f'''<div data-hold="Narrated evidence inspection" class="content"><p class="eyebrow">SEPARATE AUTHORISED TEST ACCOUNT</p><h1 style="margin-top:24px">A named person signs.</h1><div class="row" style="margin-top:42px"><div class="panel" style="width:760px"><p class="eyebrow">SERVER CHECKS</p><div class="stack" style="margin-top:26px"><p class="body">Identity + office authority</p><p class="body">Committee quorum</p><p class="body">Gate-bound TOTP assertion</p><p class="body">Replay protection</p></div></div><div class="panel" style="width:936px"><p class="eyebrow">VERIFICATION RESPONSE · EXCERPT</p><pre class="code" style="margin-top:25px">{esc(json.dumps({k:proof['boundary']['verified'][k]for k in ['status','approver','signatureValid']},indent=2))}</pre><p class="body green" style="margin-top:18px">Receipt: SIMULATED</p><p class="small" style="margin-top:14px">{esc(proof['boundary']['verified']['receipt']['submissionId'])}</p></div></div></div>''',
 'evidence':'''<div data-hold="Narrated evidence inspection" class="content"><p class="eyebrow">REPRODUCE THE RESULT</p><h1 style="margin-top:24px">An inspectable review.</h1><div class="row" style="margin-top:42px"><div class="panel" style="width:810px"><p class="eyebrow">VERIFIED 4 NOVEMBER 2026</p><div class="stack" style="margin-top:28px"><p class="body">509 tests · 0 failures</p><p class="body">Production build + TypeScript pass</p><p class="body">Meta + Llama injection probes pass</p><p class="body">Source files + model output + receipt</p></div></div><div class="panel" style="width:886px"><p class="eyebrow">HUMAN IMPACT STUDY</p><h2 style="margin-top:28px">Prepared. Results pending.</h2><p class="body" style="margin-top:26px">Two officers. Counterbalanced cases. Time, material issues and corrections.</p><p class="small accent" style="margin-top:24px">No measured savings or funds recovered are claimed.</p></div></div></div>''',
 'close':'''<div data-hold="Narrated evidence inspection" class="content" style="text-align:center"><p class="eyebrow">BUILT BY CHUNGU CHAMA · CHAMA18</p><h1 style="font-size:142px;margin-top:38px">QUORUM<span class="accent">.</span></h1><p class="body" style="margin:32px auto 0;width:1400px">The agent prepares the file.</p><p class="body">The authorised committee makes the decision.</p><div class="row" style="justify-content:center;margin-top:38px"><span class="pill">quorum-solutions.com</span><span class="pill">github.com/CHAMA18/the-bid-box-challenge</span></div><p class="small accent" style="margin-top:32px">Next: one procurement unit · one retrospective tender</p></div>'''
}
foot={
 'stakes':'Source: World Bank, 2023 · procurement averages 17% of GDP across Africa · source notes in the submission',
 'record':'Synthetic documents and starting state · Zambia · ZMW · no real supplier tax records',
 'model':'Exact source matching checks quotation existence. The committee checks interpretation and retains official scores.',
 'refusal':'Response excerpts from SUBMISSION/evidence/current-run/proof.json · no national filing request',
 'signature':'Local filing simulation · fictional authorised account · no government portal transaction',
 'evidence':'Source: dated verification artifacts · automated tests are separate from officer validation',
 'close':'Music: Signal to Noise — Scott Buckley · CC BY 4.0 · creator-authorised generated narration'
}
for i,scene in enumerate(scenes):
 sid=scene['id'];duration=scene['end']-scene['start']
 animation=f'''const tl=gsap.timeline({{paused:true}});tl.fromTo('#{sid} .content',{{opacity:1,y:18}},{{opacity:1,y:0,duration:.6,ease:'power3.out'}},.05);'''
 if sid in ['record','model']:animation+=f"tl.fromTo('#{sid} .rule',{{scaleX:0}},{{scaleX:1,duration:1,ease:'power2.inOut'}},1);"
 if sid=='record':animation+="tl.fromTo('#record-delivery',{opacity:0},{opacity:1,duration:.25,immediateRender:false},11);"
 if sid=='model':animation+="tl.to('#model-supported',{y:-15,duration:11,ease:'none'},8);"
 if sid=='refusal':animation+="tl.fromTo('#refusal-stepup',{opacity:0,y:12},{opacity:1,y:0,duration:.6},9);tl.fromTo('#refusal-pending',{opacity:0,y:12},{opacity:1,y:0,duration:.6},18);"
 animation+=f"window.__timelines['{sid}']=tl;"
 body=f'''<template><style>#{sid}{{width:100%;height:100%;position:relative;overflow:hidden;background:#101217}}</style><div id="{sid}" data-composition-id="{sid}" data-duration="{duration}" data-width="1920" data-height="1080"><div class="header"><strong>QUORUM<span class="accent">.</span></strong><span>{i+1:02} / 07 · {esc(sid.upper())}</span></div>{contents[sid]}<div class="foot">{esc(foot[sid])}</div></div><script>{animation}</script></template>'''
 (P/'compositions'/f'{sid}.html').write_text(body)
# Captions use ASR turn boundaries and source script wording. Within-turn phrase
# timings are proportional and are recorded as estimated, not word-level alignment.
captions=json.loads((OLD/'review/rubric-aligned-captions.json').read_text())
shutil.copy2(OLD/'review/rubric-word-alignment-report.json',P/'review/word-alignment-report.json')
# Correct recognised spellings without changing spoken content.
for c in captions:
 c['text']=c['text'].replace('Landgraph','LangGraph').replace('quorum','Quorum')
(P/'captions.json').write_text(json.dumps(captions,indent=2)+'\n')
caphtml=[];captl="const tl=gsap.timeline({paused:true});"
for i,c in enumerate(captions):
 caphtml.append(f'''<div id="caption-{i}" class="clip caption" data-start="{c['start']:.3f}" data-duration="{c['end']-c['start']:.3f}" data-track-index="1"><span>{esc(c['text'])}</span></div>''')
 def stamp(t):
  ms=round(t*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
with (P/'Quorum-Rubric.srt').open('w')as f:
 for i,c in enumerate(captions):f.write(f"{i+1}\n{stamp(c['start'])} --> {stamp(c['end'])}\n{c['text']}\n\n")
(P/'compositions/captions.html').write_text('<template><style>#captions{width:100%;height:100%;position:relative;pointer-events:none}</style><div id="captions" data-composition-id="captions" data-width="1920" data-height="1080" data-duration="180">'+''.join(caphtml)+"</div><script>const tl=gsap.timeline({paused:true});window.__timelines['captions']=tl;</script></template>")
mounts=''.join(f'''<div id="{s['id']}" class="clip scene" data-composition-id="{s['id']}" data-composition-src="compositions/{s['id']}.html" data-start="{s['start']}" data-duration="{s['end']-s['start']}" data-width="1920" data-height="1080" data-track-index="0" data-track-kind="graphics"></div>'''for s in scenes)
(P/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><title>Quorum — evidence-led submission demo</title><script src="assets/gsap.min.js"></script><style>{STYLE}#main{{position:relative;width:100%;height:100%;overflow:hidden}}.scene{{position:absolute;inset:0}}</style></head><body><div id="main" data-composition-id="main" data-duration="180" data-width="1920" data-height="1080" data-fps="30">{mounts}<div id="captions" class="clip" data-composition-id="captions" data-composition-src="compositions/captions.html" data-start="0" data-duration="180" data-width="1920" data-height="1080" data-track-index="1" data-track-kind="captions" style="position:absolute;inset:0;z-index:100;pointer-events:none"></div><audio id="master-audio" src="assets/master.wav" data-start="0" data-duration="180" data-track-index="2" data-volume="1"></audio></div><script>const tl=gsap.timeline({{paused:true}});tl.to('#main',{{opacity:1,duration:180,ease:'none'}},0);window.__timelines['main']=tl;</script></body></html>''')
(P/'BRIEF.md').write_text('---\nworkflow: hyperframes\nflow: automation\nstoryboard: no\n---\nThe user authorised resolution of every rubric issue without stopping. Preserve prior editions. Create a separate 180-second evidence-led Zambia demonstration from actual product captures and explicitly labelled API response excerpts. Render a 4K delivery after QA. No generated product interaction, unsupported loss statistic, claimed human validation or national filing. Keep the creator-authorised Lusaka voice and existing music licence.\n')
shutil.copy2(OLD/'docs/STORYBOARD.md',P/'docs/STORYBOARD.md')
(P/'.gitignore').write_text('.hyperframes/\n*.mp4\nassets/*.wav\nassets/*.mp3\nreview/*.png\nreview/*.jpg\nrenders/\n')
(P/'hyperframes.json').write_text(json.dumps({'paths':{'blocks':'compositions','components':'compositions/components','assets':'assets'},'media':{'autoProxy':True},'authoringSkill':'general-video'},indent=2)+'\n')
(P/'review/caption-method.json').write_text(json.dumps({'method':'Local Whisper word timestamps, matched to source wording; substitutions interpolated within recognised spans','wordLevelAlignment':True,'manualListeningPerformed':False,'captionCount':len(captions)},indent=2)+'\n')
print(P)
